pub fn changed(
    before: &[(&str, &str)],
    after: &[(&str, &str)],
) -> Vec<String> {
    let a: std::collections::BTreeMap<_, _> =
        before.iter().copied().collect();
    let b: std::collections::BTreeMap<_, _> =
        after.iter().copied().collect();
    a.keys()
        .chain(b.keys())
        .copied()
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .filter(|k| a.get(k) != b.get(k))
        .map(str::to_owned)
        .collect()
}

fn main() {
    assert_eq!(
        changed(&[("a", "1")], &[("a", "2"), ("b", "3")]),
        vec!["a".to_owned(), "b".to_owned()],
        "case 1"
    );
    assert_eq!(changed(&[], &[]), Vec::<String>::new(), "case 2");
    assert_eq!(
        changed(&[("gone", "x")], &[]),
        vec!["gone".to_owned()],
        "case 3"
    );
    assert_eq!(
        changed(&[("a", "1")], &[("a", "1")]),
        Vec::<String>::new(),
        "case 4"
    );
    println!("worked example passed");
}

